// Pull based config client, poll every 30 seconds
let config = await configStore.fetch("payment-service");

setInterval(async () => {
  try {
    config = await configStore.fetch("payment-service");
  } catch (err) {
    console.warn("config fetch failed, keeping last known values");
  }
}, 30000);

function getRateLimit() {
  return config.rateLimitPerSecond;
}

