// Push based config client, watch for changes
const watcher = await etcd.watch().key("config/payment-service/rateLimit").create();

let rateLimit = 100;

watcher.on("put", (event) => {
  rateLimit = Number(event.value.toString());
  console.log("rate limit updated live to", rateLimit);
});

