class LiveRateLimiter {
  constructor(configStore, serviceName) {
    this.limit = 100; // sane default if the store is unreachable at boot
    this.serviceName = serviceName;
    this.configStore = configStore;
  }

  async start() {
    try {
      const initial = await this.configStore.fetch(this.serviceName);
      this.limit = initial.rateLimitPerSecond;
    } catch (err) {
      console.warn("using default rate limit, config store unreachable at startup");
    }

    this.configStore.watch(this.serviceName, (updated) => {
      this.limit = updated.rateLimitPerSecond;
      console.log(`rate limit updated live to ${this.limit} req/sec`);
    });
  }

  allow(clientId, currentCount) {
    return currentCount < this.limit;
  }
}

const limiter = new LiveRateLimiter(configStore, "checkout-service");
await limiter.start();

